def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    # Iterate from the last carpet to the first (topmost is the last one placed)
    for i in range(n - 1, -1, -1):
        a, b, g, k = carpets[i]
        # Check if point (x, y) is within the carpet
        # Carpet covers x in [a, a+g) and y in [b, b+k)
        if a <= x < a + g and b <= y < b + k:
            return i + 1  # Return 1-based index
    return -1

