def decode(encoded: str, original: str, message: str) -> str:
    # Build the mapping from encoded letters to original letters
    mapping = {}

    # Check if lengths match
    if len(encoded) != len(original):
        return "Failed"

    # Build the mapping
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            # If we've seen this encoded character before, check for contradiction
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            mapping[enc_char] = orig_char

    # Check if the mapping is a bijection (each original letter maps to exactly one encoded letter)
    # We need to ensure that no two different encoded letters map to the same original letter
    reverse_mapping = {}
    for enc_char, orig_char in mapping.items():
        if orig_char in reverse_mapping:
            # Two different encoded letters map to the same original letter - contradiction
            return "Failed"
        reverse_mapping[orig_char] = enc_char

    # Now decode the message
    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            # If a character in the message is not in the mapping, we cannot decode it
            return "Failed"

    return ''.join(decoded)

